// Your wave colors in HSV
const uint8_t wave_colors[][3] = {
    {213, 255, 255}, // Purple (was 300° -> 300*255/360 = 213)
    {191, 255, 255}, // Deep blue (was 270° -> 270*255/360 = 191)
    {170, 255, 255}, // Blue (was 240° -> 240*255/360 = 170)
};

void rgb_wave_gradient(void) {
    static uint16_t timer = 0;
    static uint8_t  pos   = 0;

    if (timer_elapsed(timer) > 50) {
        timer = timer_read();

        for (uint8_t i = 0; i < RGBLIGHT_LED_COUNT; i++) {
            uint8_t wave_pos = (pos + (i * 255 / RGBLIGHT_LED_COUNT)) % 255;

            HSV hsv;
            if (wave_pos < 85) {
                // Purple to deep blue
                uint8_t blend = wave_pos * 3;
                hsv.h         = 213 - ((213 - 191) * blend) / 255; // 213 to 191
                hsv.s         = 255;
                hsv.v         = 255;
            } else if (wave_pos < 170) {
                // Deep blue to blue
                uint8_t blend = (wave_pos - 85) * 3;
                hsv.h         = 191 - ((191 - 170) * blend) / 255; // 191 to 170
                hsv.s         = 255;
                hsv.v         = 255;
            } else {
                // Blue back to purple (wrapping)
                uint8_t blend = (wave_pos - 170) * 3;
                hsv.h         = 170 + ((213 - 170) * blend) / 255; // 170 to 213
                hsv.s         = 255;
                hsv.v         = 255;
            }

            RGB rgb = hsv_to_rgb(hsv);
            rgblight_setrgb_at(rgb.r, rgb.g, rgb.b, i);
        }

        pos += 2;
        if (pos >= 255) pos = 0;
    }
}

void matrix_init_user(void) {
    // Set encoder pins as input high.
    setPinInputHigh(GP12);
    setPinInputHigh(GP13);
}

void matrix_scan_user(void) {
    rgb_wave_gradient();
}

bool encoder_update_user(uint8_t index, bool clockwise) {
    drv2605l_pulse(DRV2605L_EFFECT_SHARP_CLICK_100);
    return true;
}

